message.content:
{
  "answer_markdown": "If a Workspace in Studio reaches its monthly spending limit, API access for that Workspace is suspended until the next month begins or an admin increases the limit. Additionally, if recent invoice payments fail, access can also be affected until the payments are processed again [1, 2, 4].\n\nA Workspace spending limit **cannot exceed** the Organization spending limit. This means that even if a Workspace is configured with a lower limit, it will always be capped by the Organization's overall limit [1, 3, 4, 6].",
  "citations": [
    {
      "n": 1,
      "quote": "If the Organization reaches its monthly spending limit, API access can be suspended until the next month begins or an admin increases the limit. If recent invoice payments fail, access can also be affected until the payments are processed again."
    },
    {
      "n": 2,
      "quote": "If a Workspace reaches its monthly spending limit, API access for that Workspace is suspended until the next month begins or an admin increases the limit. If recent invoice payments fail, access can also be affected until the payments are processed again."
    },
    {
      "n": 3,
      "quote": "If the limit is reached, API access can be suspended until the next month begins or an admin increases the limit. If recent invoice payments fail, access can also be affected until the payments are processed again."
    },
    {
      "n": 4,
      "quote": "If a Workspace reaches its monthly spending limit, API access for that Workspace is suspended until the next month begins or the limit is increased. If a recent payment fails, access can be affected until the payment is processed again."
    },
    {
      "n": 6,
      "quote": "The Organization policy is the ceiling. Workspace limits can be stricter, but they cannot exceed the Organization maximum."
    }
  ],
  "insufficient_evidence": false
}

